begin;
set local search_path = public, extensions;
select extensions.plan(29);
insert into auth.users (instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000', id, 'authenticated','authenticated',email,'',now(),'{"provider":"email","providers":["email"]}','{"display_name":"Privacy test"}',now(),now(),'','','',''
from (values ('99790000-0000-4000-8000-000000000001'::uuid,'privacy-a@pocketpass.test'),('99790000-0000-4000-8000-000000000002'::uuid,'privacy-b@pocketpass.test'),('99790000-0000-4000-8000-000000000003'::uuid,'privacy-c@pocketpass.test')) as fixture(id,email);
insert into public.friendships(user_low,user_high,created_by) values ('99790000-0000-4000-8000-000000000001','99790000-0000-4000-8000-000000000002','99790000-0000-4000-8000-000000000001'),('99790000-0000-4000-8000-000000000001','99790000-0000-4000-8000-000000000003','99790000-0000-4000-8000-000000000001');
insert into public.conversations(id,kind,created_by,direct_user_low,direct_user_high) values ('99790000-0000-4000-8000-000000000010','direct','99790000-0000-4000-8000-000000000001','99790000-0000-4000-8000-000000000001','99790000-0000-4000-8000-000000000002');
insert into public.conversations(id,kind,created_by,title) values ('99790000-0000-4000-8000-000000000011','group','99790000-0000-4000-8000-000000000001','Existing'),('99790000-0000-4000-8000-000000000012','group','99790000-0000-4000-8000-000000000001','Add test');
insert into public.conversation_members(conversation_id,user_id,role) values ('99790000-0000-4000-8000-000000000010','99790000-0000-4000-8000-000000000001','owner'),('99790000-0000-4000-8000-000000000010','99790000-0000-4000-8000-000000000002','member'),('99790000-0000-4000-8000-000000000011','99790000-0000-4000-8000-000000000001','owner'),('99790000-0000-4000-8000-000000000011','99790000-0000-4000-8000-000000000002','member'),('99790000-0000-4000-8000-000000000012','99790000-0000-4000-8000-000000000001','owner'),('99790000-0000-4000-8000-000000000012','99790000-0000-4000-8000-000000000003','member');
select extensions.ok(not (select block_messages from public.profiles where user_id='99790000-0000-4000-8000-000000000002'), 'Existing accounts default to receiving messages');
select extensions.ok(not has_function_privilege('anon','public.set_message_privacy(boolean,uuid)','execute'), 'Anonymous callers cannot save privacy');
select extensions.ok(not has_column_privilege('authenticated','public.profiles','block_messages','update'), 'Clients cannot bypass the preference RPC');
select extensions.ok(not has_column_privilege('authenticated','public.profiles','block_invites','update'), 'Clients cannot directly change invite privacy');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.lives_ok($$select public.send_message('99790000-0000-4000-8000-000000000020','99790000-0000-4000-8000-000000000010','99790000-0000-4000-8000-000000000120','Privacy test')$$, 'Friends can message before blocking');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.lives_ok($$select public.set_message_privacy(true)$$, 'Owner enables blocking');
select extensions.ok((select block_messages from public.profiles where user_id=auth.uid()), 'Server confirms blocking');
select extensions.lives_ok($$select public.set_message_privacy(true)$$, 'Setting is safely repeatable');
select extensions.throws_ok($$select public.set_message_privacy(false,'99790000-0000-4000-8000-000000000001')$$, '42501', 'A PocketPass account is required', 'Cannot change another account');
select extensions.throws_ok($$select public.set_message_privacy(null)$$, '22004', 'A blocking preference is required', 'Null setting is rejected');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000002","role":"authenticated","client_id":"third-party"}',true);
select extensions.throws_ok($$select public.set_message_privacy(false)$$, '42501', 'A PocketPass account is required', 'Connected apps cannot change privacy');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.throws_ok($$select public.send_message('99790000-0000-4000-8000-000000000021','99790000-0000-4000-8000-000000000010','99790000-0000-4000-8000-000000000121','Privacy test')$$, '42501', 'This person is not accepting direct messages.', 'Existing direct messages from friends are refused');
select extensions.throws_ok($$select public.send_message('99790000-0000-4000-8000-000000000022','99790000-0000-4000-8000-000000000010','99790000-0000-4000-8000-000000000122','Image','99790000-0000-4000-8000-000000000020','{"attachment":{"mime_type":"image/gif"}}')$$, '42501', 'This person is not accepting direct messages.', 'Attachments cannot bypass message blocking');
select extensions.lives_ok($$select public.create_group_conversation('Allowed new group',array['99790000-0000-4000-8000-000000000002']::uuid[],'99790000-0000-4000-8000-000000000030')$$, 'Blocking direct messages does not prevent group invitations');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.lives_ok($$select public.set_invite_privacy(true)$$, 'Owner separately blocks invitations');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.throws_ok($$select public.add_group_members('99790000-0000-4000-8000-000000000012',array['99790000-0000-4000-8000-000000000002']::uuid[],'99790000-0000-4000-8000-000000000031')$$, '42501', 'This person is not accepting group invitations.', 'Adding a friend with invitations blocked is refused');
select extensions.ok(exists(select 1 from public.conversation_members where conversation_id='99790000-0000-4000-8000-000000000011' and user_id='99790000-0000-4000-8000-000000000002' and left_at is null), 'Blocking does not remove existing membership');
select extensions.lives_ok($$select public.send_message('99790000-0000-4000-8000-000000000023','99790000-0000-4000-8000-000000000011','99790000-0000-4000-8000-000000000123','Privacy test')$$, 'Existing group still receives messages');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.lives_ok($$select public.send_message('99790000-0000-4000-8000-000000000024','99790000-0000-4000-8000-000000000011','99790000-0000-4000-8000-000000000124','Privacy test')$$, 'Blocked account can still send in existing group');
select extensions.lives_ok($$select public.send_message('99790000-0000-4000-8000-000000000025','99790000-0000-4000-8000-000000000010','99790000-0000-4000-8000-000000000125','Privacy test')$$, 'Blocking incoming does not prevent outgoing direct messages');
reset role;
select extensions.ok((select count(*) from public.messages where conversation_id='99790000-0000-4000-8000-000000000010')=2, 'Rejected deliveries create no message rows');
select extensions.ok((select sum(event_count) from public.notifications where conversation_id='99790000-0000-4000-8000-000000000010')=2, 'Rejected deliveries create no notifications');
select extensions.ok(exists(select 1 from public.conversations where title='Allowed new group'), 'Message blocking alone allows the new group');
update public.conversation_members set left_at=now() where conversation_id='99790000-0000-4000-8000-000000000011' and user_id='99790000-0000-4000-8000-000000000002';
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.throws_ok($$select public.add_group_members('99790000-0000-4000-8000-000000000011',array['99790000-0000-4000-8000-000000000002']::uuid[],'99790000-0000-4000-8000-000000000032')$$, '42501', 'This person is not accepting group invitations.', 'A former group member cannot be re-added while invitations are blocked');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.lives_ok($$select public.set_message_privacy(false)$$, 'Owner can turn blocking off');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.lives_ok($$select public.send_message('99790000-0000-4000-8000-000000000026','99790000-0000-4000-8000-000000000010','99790000-0000-4000-8000-000000000126','Privacy test')$$, 'Direct messages resume after unblocking');
select extensions.throws_ok($$select public.add_group_members('99790000-0000-4000-8000-000000000012',array['99790000-0000-4000-8000-000000000002']::uuid[],'99790000-0000-4000-8000-000000000034')$$, '42501', 'This person is not accepting group invitations.', 'Unblocking messages does not unblock invitations');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.lives_ok($$select public.set_invite_privacy(false)$$, 'Owner unblocks invitations');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"99790000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.lives_ok($$select public.add_group_members('99790000-0000-4000-8000-000000000012',array['99790000-0000-4000-8000-000000000002']::uuid[],'99790000-0000-4000-8000-000000000033')$$, 'Group adds resume after unblocking');
reset role;
select * from extensions.finish();
rollback;
